# How else a saint is named: the place he is known by. German forms this with
# von and the place, so the ones that are simply a rank and a town are
# assembled from the map above rather than written again - a town cannot then
# be spelled one way in a place line and another way in a title. Everything
# with a second clause in it is written out below, because no rule assembles
# "Abbot of Peshnosha, disciple of Saint Sergius of Radonezh".
TITLE_RANK = {
    "Abbess": "Äbtissin",
    "Abbot": "Abt",
    "Archbishop": "Erzbischof",
    "Archdeacon": "Erzdiakon",
    "Bishop": "Bischof",
    "Enlightener": "Erleuchter",
    "Eparch": "Eparch",
    "First Archbishop": "Erster Erzbischof",
    "First Bishop": "Erster Bischof",
    "First Metropolitan": "Erster Metropolit",
    "First Wonderworker": "Erster Wundertäter",
    "Grand Duchess": "Grossfürstin",
    "Hermit": "Einsiedler",
    "Igumen": "Igumen",
    "King": "König",
    "Martyrs": "Märtyrer",
    "Metropolitan": "Metropolit",
    "New Martyrs and Confessors": "Neumärtyrer und Bekenner",
    "Patriarch": "Patriarch",
    "Physician": "Arzt",
    "Pope": "Papst",
    "Prince": "Fürst",
    "Princess": "Fürstin",
    "Protomartyr": "Erzmärtyrer",
    "Queen": "Königin",
    "Virgin Martyr": "Jungfrau und Märtyrerin",
    "Wonderworker": "Wundertäter",
    "Wonderworkers": "Wundertäter",
}


# The preposition a bare place-title takes. German distinguishes where a
# saint is from and where he suffered, and the calendar's English does not
# always, so the reading is taken from the word it uses: "of" is the name he
# is known by and takes von, "at" and "in" are where the thing happened and
# take zu and in.
TITLE_PREP = {"of ": "von ", "at ": "zu ", "in ": "in ", "near ": "bei ",
              "from ": "aus "}


def titles(phrases):
    """A rank and a town joined with von, and the bare place-titles."""
    out = {}
    for p in phrases:
        head, sep, tail = p.partition(" of ")
        if sep and head in TITLE_RANK and tail in PARTS:
            out[p] = "%s von %s" % (TITLE_RANK[head], PARTS[tail])
            continue
        for pre, de in TITLE_PREP.items():
            if p.startswith(pre) and p[len(pre):] in PARTS:
                out[p] = de + PARTS[p[len(pre):]]
                break
    return out


